import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Three-weapon test numbers","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/combat/numeric-prototype.md","filePath":"en/guide/combat/numeric-prototype.md"}'),n={name:"en/guide/combat/numeric-prototype.md"};function o(s,t,i,l,h,c){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="three-weapon-test-numbers" tabindex="-1">Three-weapon test numbers <a class="header-anchor" href="#three-weapon-test-numbers" aria-label="Permalink to &quot;Three-weapon test numbers&quot;">​</a></h1><p><strong>Status:</strong> Experimental prototype numbers · Not implemented.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>These are Experimental numbers for Longsword, Spear and War Hammer, not implemented balance.</li><li>Costs and phases apply to both modes; Modern chooses when an available action starts.</li><li>Read the full numeric profile for active windows, modifiers and rounding before calculating outcomes.</li></ul><p>These are first-pass test values for future playable trials, not live balance. Values assume Practiced, neutral handling and Stable rhythm.</p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Weapon</th><th>Identity</th><th>Basic Legacy interval</th></tr></thead><tbody><tr><td>Longsword</td><td>Versatile close control</td><td>1300 ms</td></tr><tr><td>Spear</td><td>Spacing and approach punishment</td><td>1550 ms</td></tr><tr><td>War Hammer</td><td>Expensive, committed impact</td><td>2200 ms</td></tr></tbody></table><p>Intervals assume full stamina and DEX 50. Modern begins when you choose an available action; both modes must finish wind-up, active phase and recovery.</p><h2 id="longsword" tabindex="-1">Longsword <a class="header-anchor" href="#longsword" aria-label="Permalink to &quot;Longsword&quot;">​</a></h2><table tabindex="0"><thead><tr><th>SA / action</th><th>Type</th><th>Reach</th><th>Cost</th><th>Wind-up</th><th>Recovery</th><th>Purpose</th></tr></thead><tbody><tr><td>Basic Slash</td><td>Basic</td><td>1</td><td>10</td><td>250 ms</td><td>600 ms</td><td>Reliable cut</td></tr><tr><td>Thrust</td><td>Offense</td><td>1</td><td>13</td><td>300 ms</td><td>650 ms</td><td>Narrow precision</td></tr><tr><td>Feint</td><td>Deception</td><td>1</td><td>7</td><td>250 ms</td><td>400 ms</td><td>Bait defense; no damage</td></tr><tr><td>Riposte</td><td>Defense</td><td>1</td><td>15</td><td>100 ms</td><td>650 ms</td><td>Counter compatible contact</td></tr></tbody></table><h2 id="spear" tabindex="-1">Spear <a class="header-anchor" href="#spear" aria-label="Permalink to &quot;Spear&quot;">​</a></h2><table tabindex="0"><thead><tr><th>SA / action</th><th>Type</th><th>Reach</th><th>Cost</th><th>Wind-up</th><th>Recovery</th><th>Purpose</th></tr></thead><tbody><tr><td>Basic Thrust</td><td>Basic</td><td>2</td><td>12</td><td>350 ms</td><td>700 ms</td><td>Keep distance</td></tr><tr><td>Lunge</td><td>Offense</td><td>3</td><td>22</td><td>500 ms</td><td>1000 ms</td><td>Committed extension</td></tr><tr><td>Brace</td><td>Defense</td><td>2</td><td>18</td><td>150 ms</td><td>850 ms</td><td>Answer commitment</td></tr><tr><td>Sweep</td><td>Offense</td><td>1</td><td>20</td><td>450 ms</td><td>850 ms</td><td>Short arc, up to 2 hostiles</td></tr></tbody></table><h2 id="war-hammer" tabindex="-1">War Hammer <a class="header-anchor" href="#war-hammer" aria-label="Permalink to &quot;War Hammer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>SA / action</th><th>Type</th><th>Reach</th><th>Cost</th><th>Wind-up</th><th>Recovery</th><th>Purpose</th></tr></thead><tbody><tr><td>Basic Swing</td><td>Basic</td><td>1</td><td>17</td><td>500 ms</td><td>1000 ms</td><td>Blunt pressure</td></tr><tr><td>Heavy Blow</td><td>Offense</td><td>1</td><td>28</td><td>750 ms</td><td>1400 ms</td><td>Punish position</td></tr><tr><td>Crushing Arc</td><td>Offense</td><td>2</td><td>30</td><td>650 ms</td><td>1300 ms</td><td>Wide pressure, up to 2 hostiles</td></tr><tr><td>Guard Break</td><td>Offense</td><td>1</td><td>24</td><td>600 ms</td><td>1100 ms</td><td>Weaken an active stance</td></tr></tbody></table><p>Tables omit active duration for scanning: see the full profile before calculating total action time. Riposte&#39;s baseline active window is 450 ms; Brace&#39;s is 1600 ms. A successful trigger ends the remaining defensive window and starts recovery.</p><h2 id="trade-offs" tabindex="-1">Trade-offs <a class="header-anchor" href="#trade-offs" aria-label="Permalink to &quot;Trade-offs&quot;">​</a></h2><ul><li>Brace reduces a compatible impact by 35%; Riposte by 25%, with one eligible counter attempt.</li><li>Guard Break halves that reduction for its own hit and triggers no stance counter. It adds no stun or permanent armor break.</li><li>Feint, delay or flank can waste a defense. No compatible contact means no counter.</li><li>No action grants invisible reach, a free extra swing or unbounded burst damage.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/combat/legacy-and-modern.html">Modes</a> · <a href="/Syrolands-Public/en/guide/combat/flow.html">Flow</a> · <a href="/Syrolands-Public/en/guide/characters/familiarity.html">Familiarity</a> · <a href="/Syrolands-Public/en/game-design/combat/numeric-prototype.html">Full numeric profile</a></p>',19)])])}const p=e(n,[["render",o]]);export{u as __pageData,p as default};
